from pathlib import Path
import argparse,csv,hashlib,importlib.util,json,math,shutil,tarfile
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=argparse.ArgumentParser();p.add_argument('--archive',type=Path,required=True);p.add_argument('--fixture',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
fixture=json.loads(a.fixture.read_text());references={r['seed']:r for r in fixture['episodes']};rows=[];curves={}
with tarfile.open(a.archive) as tar:
 for name in sorted(n for n in tar.getnames() if n.endswith('/result.json')):
  result=json.load(tar.extractfile(name));prefix=name[:-len('result.json')];snaps=[json.loads(l) for l in tar.extractfile(prefix+'physical.jsonl')];steps=[json.loads(l) for l in tar.extractfile(prefix+'commands.jsonl')];reference=references[result['seed']];actions=reference['clean_actions_rad' if result['commands']=='clean' else 'executed_actions_rad'];assert len(steps)==len(actions) and len(snaps)==len(actions)+1
  for i,(step,command) in enumerate(zip(steps,actions)):
   expected=np.asarray(command,dtype=np.float32).astype(float).tolist();payload=step['command'];ack=step['ack'];assert step['action_index']==i and payload['command']==expected and payload['advance'] is True
   assert ack['applied_command']==expected and snaps[i+1]['drive_targets']==expected
   assert payload['epoch']==ack['epoch']==snaps[i]['epoch']==snaps[i+1]['epoch'] and payload['observation_stamp_ns']==ack['observation_stamp_ns']==ack['application_stamp_ns']==snaps[i]['sim_ns']
   assert abs(snaps[i+1]['sim_ns']-snaps[i]['sim_ns']-1e9/30)<1000
  q=np.asarray([s['state'] for s in snaps[:-1]]);r=np.asarray(reference['recorded_states_rad']);e=np.degrees(q-r);assert np.allclose(np.sqrt(np.mean(e*e,axis=0)),result['state_tracking']['rms_deg'],rtol=0,atol=1e-12)
  rows.append(dict(seed=result['seed'],color=result['color'],commands=result['commands'],actions=len(actions),target_readback_exact=len(actions),single_frame_advances=len(actions),grasp=result['grasp_success'],success=result['success'],wall_s=result['wall_s'],preclosure_tcp_rms_mm=result['tcp_tracking']['preclosure_rms_mm'],preclosure_tcp_max_mm=result['tcp_tracking']['preclosure_max_mm'],full_tcp_rms_mm=result['tcp_tracking']['rms_mm'],full_tcp_max_mm=result['tcp_tracking']['max_mm'],**{'rms_'+n+'_deg':v for n,v in zip(('pan','lift','elbow','wrist_flex','wrist_roll','gripper'),result['state_tracking']['rms_deg'])},**{'max_'+n+'_deg':v for n,v in zip(('pan','lift','elbow','wrist_flex','wrist_roll','gripper'),result['state_tracking']['max_abs_deg'])}))
  if result['commands']=='executed':curves[result['color']]=(np.arange(len(q))/30,e)
(a.out/'replay-metrics.json').write_text(json.dumps(rows,indent=2)+'\n')
with (a.out/'replay-metrics.csv').open('w') as f:w=csv.DictWriter(f,list(rows[0]));w.writeheader();w.writerows(rows)
